<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kafka 订单实验室 · PHP 订单页面</title>
<style>
:root{--ink:#20313b;--muted:#526674;--line:#cddae1;--blue:#175bc0;--orange:#a24b13;--paper:#f6f8f7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 system-ui,"PingFang SC",sans-serif}main{max-width:1260px;margin:auto;padding:40px 28px 60px}h1{font-size:32px;line-height:1.4;margin:0 0 12px}h2{font-size:21px;margin:0 0 16px}h3{font-size:17px;margin:0 0 9px}p{margin:7px 0 16px}.muted{color:var(--muted)}.route{display:flex;gap:12px;align-items:center;margin:25px 0 30px;flex-wrap:wrap}.route b{color:var(--blue)}.route span{font-size:14px;color:var(--muted)}.panel{background:#fff;border:1px solid var(--line);border-radius:9px;padding:24px;margin-bottom:22px}.form{display:grid;grid-template-columns:2fr 1fr 1fr;gap:16px}label{font-size:14px;font-weight:600}input{display:block;width:100%;padding:10px 12px;border:1px solid #a6b8c4;border-radius:5px;font:16px system-ui;margin-top:6px}button{padding:10px 16px;border:1px solid var(--line);border-radius:5px;background:#fff;color:var(--ink);font:600 15px/1.5 system-ui;cursor:pointer}button.primary{background:var(--blue);border-color:var(--blue);color:#fff}button:disabled{opacity:.5;cursor:wait}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:3px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}#feedback{margin:12px 0 0;min-height:27px;color:var(--blue);overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:22px}.order-list{display:flex;flex-direction:column;gap:9px}.order-list button{text-align:left;font-weight:450}.order-list button.selected{border-color:var(--blue);background:#edf4fe}.order-list small{display:block;color:var(--muted)}.detail-head{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.badge{font-size:15px;color:var(--orange);font-weight:600}.badge.CONFIRMED{color:#207452}.badge.REJECTED{color:#a33730}code{font:14px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.order-id{display:block;margin:8px 0 18px;color:var(--muted)}.steps{padding:0;list-style:none;margin:20px 0}.steps li{padding:12px 0;border-top:1px solid #e2e8ec}.steps strong{display:block;font-size:16px}.steps small{color:var(--muted);font-size:14px}.messages{display:grid;grid-template-columns:1fr 1fr;gap:22px}.message{min-width:0}.meta{white-space:pre-line;color:var(--muted);font:14px/1.8 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere;margin-bottom:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:460px;overflow:auto;background:#f2f6fa;padding:16px;border-radius:5px;font:13px/1.8 ui-monospace,SFMono-Regular,monospace;margin:10px 0}details summary{cursor:pointer;color:var(--blue);font-size:14px}#empty{color:var(--muted);padding:25px 0}.note{font-size:14px;color:var(--muted);border-top:1px solid var(--line);padding-top:15px;margin-top:20px}.error{color:#a33730!important}footer{font-size:14px;color:var(--muted);margin-top:20px}@media(max-width:760px){main{padding:24px 18px}h1{font-size:26px}.form,.grid,.messages{grid-template-columns:1fr}.panel{padding:20px}.route{gap:8px}.route b{font-size:14px}.order-list{max-height:240px;overflow:auto}.detail-head{display:block}}
</style></head><body><main>
<h1>订单怎样从 PHP 走到 Java，再回到 PHP？</h1>
<p class="muted">创建一笔订单。PHP 先保存并发送消息，Java 读取后审核，再发回结果；PHP 收到结果后更新订单。</p>
<div class="route" aria-label="消息流转路线"><b>PHP 创建订单</b><span>→ OrderCreated →</span><b>Java 审核</b><span>→ OrderReviewed →</span><b>PHP 更新结果</b></div>
<section class="panel"><h2>先创建一笔订单</h2><p class="muted">审核规则：订单总额不超过 1000 元时通过，超过时拒绝。这里不涉及真实支付。</p>
<form id="order-form"><div class="form"><label>商品名称<input id="product" name="product" value="机械键盘" required maxlength="100"></label><label>数量<input id="quantity" name="quantity" type="number" min="1" max="1000" step="1" value="2" required></label><label>单价（元）<input id="price" name="price" type="number" min="0.01" max="100000" step="0.01" value="199.00" required></label></div><div class="actions"><button class="primary" id="submit-order">创建订单（PHP）</button><button type="button" id="fill-rejected">填入拒绝案例</button><button type="button" id="refresh">刷新订单列表</button></div></form><p id="feedback" role="status" aria-live="polite">提交后，先拿到订单编号，再等待审核结果。</p></section>
<div class="grid"><aside class="panel"><h2>最近的订单</h2><div id="order-list" class="order-list"></div></aside><section class="panel"><div id="empty">创建订单后，这里会显示实际处理结果和消息位置。</div><div id="detail" hidden><div class="detail-head"><h2 id="order-title"></h2><span id="order-status" class="badge"></span></div><code id="order-id" class="order-id"></code><p id="order-reason"></p><ol id="steps" class="steps"></ol><div class="messages"><section class="message"><h3>① PHP → Java</h3><div id="created-meta" class="meta"></div><details><summary>查看 OrderCreated 消息</summary><pre id="created-json"></pre></details></section><section class="message"><h3>② Java → PHP</h3><div id="reviewed-meta" class="meta"></div><details><summary>查看 OrderReviewed 消息</summary><pre id="reviewed-json"></pre></details></section></div><p id="input-record" class="note"></p></div></section></div>
<footer>页面每 2 秒向 PHP 查询一次，显示的是 PHP 已保存的业务状态。两条消息属于不同 Topic，Offset 分别计算。完整代码阅读顺序与暂停、重放实验见项目 README.md。</footer>
</main><script>
const labels={PENDING_REVIEW:'等待审核结果',CONFIRMED:'审核通过',REJECTED:'审核拒绝'};
let orders=[],selected=null,polling=false,pendingKey=null,loadFailed=false;
const el=id=>document.getElementById(id);
function money(cents){return (Number(cents)/100).toFixed(2)}
function metadata(m){return m?`Topic: ${m.topic}\nKey: ${m.key}\nPartition: ${m.partition??'待确认'} · Offset: ${m.offset??'待确认'}`:'尚未收到 Java 结果；不会因为下单受理成功就显示审核完成。'}
function render(){
 const list=el('order-list');list.replaceChildren();
 for(const order of orders){const button=document.createElement('button');button.type='button';button.className=selected===order.orderId?'selected':'';button.textContent=order.product+' · ¥'+money(order.totalCents);const small=document.createElement('small');small.textContent=labels[order.status]+' · '+order.orderId.slice(-8);button.append(small);button.onclick=()=>{selected=order.orderId;render()};list.append(button)}
 const order=orders.find(o=>o.orderId===selected);el('empty').hidden=!!order;el('detail').hidden=!order;if(!order)return;
 el('order-title').textContent=order.product+' × '+order.quantity+' · ¥'+money(order.totalCents);
 el('order-id').textContent=order.orderId;el('order-status').textContent=labels[order.status];el('order-status').className='badge '+order.status;
 el('order-reason').textContent=order.reason||'订单已受理。页面在等待 PHP 消费并保存 Java 的审核结果。';
 const stages=[['PHP 已保存订单',order.createdAt],['PHP 发送 OrderCreated',order.outbound?.sentAt?'已收到 Kafka 写入确认':'待发送；PHP 发送进程会重试'],['Java 审核并发送结果',order.inbound?'Java 返回：'+labels[order.inbound.event.data.status]:'页面尚未收到结果，暂不知道 Java 的最新审核状态'],['PHP 消费 OrderReviewed',order.inbound?'结果已保存，随后提交消费位置':'等待结果消息']];
 const stepList=el('steps');stepList.replaceChildren();for(const [title,detail]of stages){const li=document.createElement('li');const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=detail;li.append(strong,small);stepList.append(li)}
 el('created-meta').textContent=metadata(order.outbound);el('reviewed-meta').textContent=metadata(order.inbound);
 el('created-json').textContent=JSON.stringify(order.outbound?.event??{},null,2);el('reviewed-json').textContent=order.inbound?JSON.stringify(order.inbound.event,null,2):'等待 OrderReviewed 消息';
 const input=order.inbound?.event.data.inputRecord;el('input-record').textContent=input?`Java 实际读取到：${input.topic} / Partition ${input.partition} / Offset ${input.offset}。可以与左侧 PHP 的发送确认对照。`:'先观察 PHP 的发送位置。结果到达后，这里会显示 Java 实际读到的位置。';
}
async function load(){if(polling)return;polling=true;try{const res=await fetch('/api/orders',{headers:{Accept:'application/json'}});if(!res.ok)throw Error('读取订单失败，请检查 PHP 服务。');const body=await res.json();orders=body.orders;if(loadFailed){el('feedback').className='';el('feedback').textContent='连接已恢复，订单列表已更新。';loadFailed=false}if(!selected&&orders.length)selected=orders[0].orderId;render()}catch(error){loadFailed=true;el('feedback').textContent='暂时无法连接 PHP，页面会自动重试。';el('feedback').className='error'}finally{polling=false}}
el('order-form').addEventListener('submit',async event=>{event.preventDefault();const button=el('submit-order');button.disabled=true;el('feedback').className='';
 const [whole,fraction='']=el('price').value.split('.');const cents=Number(whole)*100+Number(fraction.padEnd(2,'0'));
 const payload={product:el('product').value,quantity:Number(el('quantity').value),unitPriceCents:cents};
 const fingerprint=JSON.stringify(payload);if(!pendingKey||pendingKey.fingerprint!==fingerprint)pendingKey={fingerprint,key:crypto.randomUUID()};
 try{const res=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','Idempotency-Key':pendingKey.key},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok)throw Error(data.message||'创建失败');selected=data.orderId;pendingKey=null;el('feedback').textContent='已受理 '+data.orderId+'，正在等待审核结果。';await load()}catch(error){el('feedback').className='error';el('feedback').textContent=error.message+' 可重新提交相同内容；本次请求编号会保留。'}finally{button.disabled=false}});
el('fill-rejected').onclick=()=>{el('product').value='显示器';el('quantity').value='1';el('price').value='1200.00';el('feedback').className='';el('feedback').textContent='已填入总额 1200 元的订单，点击“创建订单”观察拒绝结果。'};
el('refresh').onclick=load;load();setInterval(load,2000);
</script></body></html>
